// Tag rules for the LABELS map (PROMPT-2 L3): derive tags from label content.
// The old code tagged ALL 511 LABELS entries 'exchange' — poisoning flow
// classification (Uniswap Router, bridges and MEV bots are NOT exchanges, so
// their txs were misclassified as Exchange Inflow/Outflow).
// Order matters: defi is checked before exchange because 'Stargate' contains
// 'Gate' — and 'Bridge'/'Router' must never land in 'exchange'.
function tagForLabel(label: string): string {
  if (/Uniswap|MakerDAO|Curve|Aave|Compound|Lido|Bridge|Router|Stargate|LayerZero/i.test(label)) return 'defi';
  if (/Binance|Coinbase|Kraken|Bitfinex|OKX|Bybit|Huobi|KuCoin|Gate|Poloniex|FTX|Bitstamp|Gemini|Crypto\.com|Upbit|Bithumb/i.test(label)) return 'exchange';
  if (/MEV Bot/i.test(label)) return 'mm';
  if (/Mining|Pool|Foundry|AntPool|F2Pool|ViaBTC|MARA|Riot/i.test(label)) return 'miner';
  if (/Tether|Circle|Treasury/i.test(label)) return 'stablecoin';
  return 'whale';
}

async function ensureKnownAddresses(db: D1Database): Promise<void> {
  try {
    // Create table (single statement to avoid D1 exec issues)
    await db.prepare(`
      CREATE TABLE IF NOT EXISTS known_addresses (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        address TEXT NOT NULL,
        label TEXT DEFAULT '',
        entity TEXT DEFAULT '',
        blockchain TEXT DEFAULT '',
        tags TEXT DEFAULT '',
        logo TEXT DEFAULT '',
        UNIQUE(address, blockchain)
      )
    `).run();
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_ka_entity ON known_addresses(entity)').run();
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_ka_address ON known_addresses(address)').run();
    await db.prepare('CREATE INDEX IF NOT EXISTS idx_ka_blockchain ON known_addresses(blockchain)').run();

    // Check seed version flag — skip if full v3 seed already applied.
    // v3 (PROMPT-2): junk purge (~3.2K rows), tag de-poisoning, Cardano drop.
    const versionRow = await db.prepare(
      "SELECT 1 as ok FROM known_addresses WHERE address = 'SEED_VERSION' AND entity = 'v3' LIMIT 1"
    ).first<{ ok: number }>();
    if (versionRow?.ok) {
      console.log('[Tracking] Full seed v3 already applied — skipping');
      return;
    }

    // Fallback threshold check for legacy deployments without the flag
    const count = await db.prepare('SELECT COUNT(*) as cnt FROM known_addresses').first<{ cnt: number }>();
    if ((count?.cnt || 0) > 10000) return; // Already seeded — expanded dataset

    console.log('[Tracking] Seeding known_addresses from LABELS + TOP_ENTITIES + SQL batches...');

    const BATCH_SIZE = 50;

    // Seed from LABELS map (whale tracking labels)
    const labelEntries: { addr: string; label: string; chain: string }[] = [];
    for (const [addr, label] of Object.entries(LABELS)) {
      let chain = 'Ethereum';
      if (addr.startsWith('bc1') || addr.startsWith('1') || addr.startsWith('3')) chain = 'Bitcoin';
      else if (addr.startsWith('T') && addr.length >= 30 && addr.length <= 40) chain = 'Tron';
      else if (addr.startsWith('sei1')) chain = 'Sei';
      else if (addr.length > 60 && addr.startsWith('0x')) chain = 'Sui';
      else if (addr.length > 40 && !addr.startsWith('0x')) chain = 'Solana';
      labelEntries.push({ addr, label, chain });
    }

    for (let i = 0; i < labelEntries.length; i += BATCH_SIZE) {
      const chunk = labelEntries.slice(i, i + BATCH_SIZE);
      await db.batch(chunk.map(entry =>
        db.prepare(
          `INSERT OR IGNORE INTO known_addresses (address, label, entity, blockchain, tags)
           VALUES (?, ?, ?, ?, ?)`
        ).bind(entry.addr, entry.label, entry.label, entry.chain, tagForLabel(entry.label))
      ));
    }

    // Seed from TOP_ENTITIES (holdings entities)
    const entityAddrEntries: { address: string; label: string; entityName: string; blockchain: string; category: string }[] = [];
    for (const entity of TOP_ENTITIES) {
      for (const addr of entity.addresses) {
        entityAddrEntries.push({
          address: addr.address,
          label: addr.label,
          entityName: entity.name,
          blockchain: addr.blockchain,
          category: entity.category,
        });
      }
    }

    for (let i = 0; i < entityAddrEntries.length; i += BATCH_SIZE) {
      const chunk = entityAddrEntries.slice(i, i + BATCH_SIZE);
      await db.batch(chunk.map(e =>
        db.prepare(
          `INSERT OR IGNORE INTO known_addresses (address, label, entity, blockchain, tags)
           VALUES (?, ?, ?, ?, ?)`
        ).bind(e.address, e.label, e.entityName, e.blockchain, e.category)
      ));
    }

    // Seed from embedded SQL batches (11,000+ addresses) — each batch is already a
    // ~100-row INSERT; group BATCH_SIZE of those per db.batch() call to cut round trips.
    for (let i = 0; i < SEED_BATCHES.length; i += BATCH_SIZE) {
      const chunk = SEED_BATCHES.slice(i, i + BATCH_SIZE);
      try {
        await db.batch(chunk.map(sql => db.prepare(sql)));
      } catch (e) {
        console.error(`[Tracking] Seed batch group ${Math.floor(i / BATCH_SIZE) + 1} failed: ${e}`);
      }
      console.log(`[Tracking] Seed batches ${Math.min(i + BATCH_SIZE, SEED_BATCHES.length)}/${SEED_BATCHES.length} complete`);
    }

    // Write seed version flag so future deploys skip re-seeding.
    // MUST be INSERT OR REPLACE: the flag row is UNIQUE(address='SEED_VERSION',
    // blockchain='system') — OR IGNORE would silently keep the old 'v2' flag and
    // trigger a full re-seed on EVERY cron start.
    await db.prepare(
      `INSERT OR REPLACE INTO known_addresses (address, label, entity, blockchain, tags)
       VALUES (?, ?, ?, ?, ?)`
    ).bind('SEED_VERSION', 'SEED_VERSION', 'v3', 'system', 'seed,meta').run();

    const finalCount = await db.prepare('SELECT COUNT(*) as cnt FROM known_addresses').first<{ cnt: number }>();
    console.log(`[Tracking] Seeding complete. Total known_addresses: ${finalCount?.cnt || 0}`);

  } catch (e) {
    console.error(`[Tracking] Error seeding known_addresses: ${e}`);
  }
}

export { LABELS, TOP_ENTITIES, SEED_BATCHES, ensureKnownAddresses };
